static int64_t z_t1881_find(const z_t1881_t* _this, const z_t46_t* _key, uint64_t _hash, int64_t* _slot_out) {
    if (_this->capacity == 0) return -1;
    uint64_t probe = _hash & (_this->capacity - 1);
    for (uint64_t i = 0; i < _this->capacity; i++) {
        int64_t slot = _this->indices[probe];
        if (slot == Z_T1881_INDEX_EMPTY) {
            if (_slot_out) *_slot_out = (int64_t)probe;
            return -1;
        }
        if (slot != Z_T1881_INDEX_DELETED) {
            if (_this->entries[slot].hash == _hash && z_t1881_keys_equal(&_this->entries[slot].key, _key)) {
                if (_slot_out) *_slot_out = (int64_t)probe;
                return slot;
            }
        }
        probe = (probe + 1) & (_this->capacity - 1);
    }
    return -1;
}

static void z_t1881_set(z_t1881_t* _this, z_t46_t _key, bool _val);
static void z_t1881_set(z_t1881_t* _this, z_t46_t _key, bool _val) {
    uint64_t h = z_t1881_hash_key(&_key);
    int64_t existing = z_t1881_find(_this, &_key, h, NULL);
    if (existing >= 0) {
        _this->entries[existing].value = _val;
        z_t46_free(&_key);
        return;
    }
    if (_this->capacity == 0 || (_this->entries_len + 1) * 3 >= _this->capacity * 2) {
        z_t1881_grow(_this);
    }
    uint64_t probe = h & (_this->capacity - 1);
    int64_t first_deleted = -1;
    for (uint64_t i = 0; i < _this->capacity; i++) {
        int64_t slot = _this->indices[probe];
        if (slot == Z_T1881_INDEX_EMPTY) {
            if (first_deleted >= 0) probe = (uint64_t)first_deleted;
            break;
        }
        if (slot == Z_T1881_INDEX_DELETED && first_deleted < 0) {
            first_deleted = (int64_t)probe;
        }
        probe = (probe + 1) & (_this->capacity - 1);
    }
    if (_this->entries_len >= _this->entries_cap) {
        uint64_t new_ec = _this->entries_cap == 0 ? 8 : _this->entries_cap * 2;
        _this->entries = (z_t1881_entry_t*)z_xrealloc(_this->entries, new_ec * sizeof(z_t1881_entry_t));
        for (uint64_t i = _this->entries_cap; i < new_ec; i++) {
            _this->entries[i] = (z_t1881_entry_t){0};
        }
        _this->entries_cap = new_ec;
    }
    int64_t new_idx = (int64_t)_this->entries_len;
    _this->entries[new_idx].alive = 1;
    _this->entries[new_idx].hash = h;
    _this->entries[new_idx].key = _key;
    _this->entries[new_idx].value = _val;
    _this->entries_len++;
    _this->indices[probe] = new_idx;
    _this->length++;
}

static z_t1093_t z_t1881_get(z_t1881_t* _this, const z_t46_t* _key);
static z_t1093_t z_t1881_get(z_t1881_t* _this, const z_t46_t* _key) {
    uint64_t h = z_t1881_hash_key(_key);
    int64_t idx = z_t1881_find(_this, _key, h, NULL);
    z_t1093_t _r;
    if (idx >= 0) {
        _r.tag = Z_OPTIONVAL_BOOL_TAG_SOME;
        _r.data.some = _this->entries[idx].value;
    } else {
        _r.tag = Z_OPTIONVAL_BOOL_TAG_NONE;
    }
    return _r;
}

static z_t1093_t z_t1881_remove(z_t1881_t* _this, const z_t46_t* _key);
static z_t1093_t z_t1881_remove(z_t1881_t* _this, const z_t46_t* _key) {
    uint64_t h = z_t1881_hash_key(_key);
    int64_t slot = -1;
    int64_t idx = z_t1881_find(_this, _key, h, &slot);
    z_t1093_t _r;
    if (idx < 0) {
        _r.tag = Z_OPTIONVAL_BOOL_TAG_NONE;
        return _r;
    }
    _r.tag = Z_OPTIONVAL_BOOL_TAG_SOME;
    _r.data.some = _this->entries[idx].value;
    z_t46_free(&_this->entries[idx].key);
    _this->entries[idx].alive = 0;
    _this->indices[slot] = Z_T1881_INDEX_DELETED;
    _this->length--;
    return _r;
}

